    private void shadow(long lifecycle,long[] values)throws Throwable{long[] read=(long[])shadowValues.invokeExact();require(read.length==6&&read[0]==lifecycle&&read[1]==values[0]&&read[2]==values[1]&&read[3]==values[2]&&read[4]==1,"complete immutable native fallback readback");}
